// server/_core/trpc.ts
import { initTRPC, TRPCError } from "@trpc/server";
import superjson from "superjson";

// shared/admin-access.ts
function isExplicitAdminAccessLevel(value) {
  return value === "system_admin" || value === "delivery_admin";
}
function hasExplicitAdminRole(user) {
  return user.role === "admin" && isExplicitAdminAccessLevel(user.adminAccessLevel);
}
function hasDeliveryCapability(user) {
  return user.role === "admin" && (user.adminAccessLevel === "delivery_admin" || user.adminAccessLevel === "system_admin");
}
function isProtectedBuiltinAdminUsername(value) {
  return typeof value === "string" && value.normalize("NFKC").trim().toLowerCase() === "admin";
}

// server/_core/trpc.ts
var t = initTRPC.context().create({
  transformer: superjson
});
var router = t.router;
var publicProcedure = t.procedure;
var protectedProcedure = t.procedure.use(({ ctx, next }) => {
  if (!ctx.user) {
    throw new TRPCError({ code: "UNAUTHORIZED", message: "Please log in" });
  }
  return next({ ctx: { ...ctx, user: ctx.user } });
});
var adminProcedure = protectedProcedure.use(({ ctx, next }) => {
  if (!hasExplicitAdminRole(ctx.user)) {
    throw new TRPCError({
      code: "FORBIDDEN",
      message: "Explicit administrator permission is required"
    });
  }
  return next({ ctx });
});

